OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'server', 'game', 'data')

def card(cid, title, text, tags, tip, *rest, **extra):
    d = {"id": cid, "title": title, "text": text, "tags": tags, "tip": tip}
    if len(rest) == 2:  # effect, targeting
        d["effect"], d["targeting"] = rest
    d.update(extra)
    return d

