def build(meta, rows):
    return {"category": meta[0], "label": meta[1], "icon": meta[2],
            "cards": [card(*r) for r in rows]}

EFFECTS = {"reveal_other", "swap_card", "immune_vote", "double_vote", "cancel_vote", "peek_other",
           "heal_self", "boost_self", "extra_time", "return_player", "reroll_card", "silence_player"}
TARGETING = {"self", "one_player", "all", "none"}

def check(name, deck):
    bad = []
    seen = set()
    for c in deck["cards"]:
        if c["id"] in seen:
            bad.append("dup id " + c["id"])
        seen.add(c["id"])
        if not (80 <= len(c["text"]) <= 200):
            bad.append("text %d %s %s" % (len(c["text"]), c["id"], c["title"]))
        if not (60 <= len(c["tip"]) <= 160):
            bad.append("tip %d %s %s" % (len(c["tip"]), c["id"], c["title"]))
        if not (2 <= len(c["tags"]) <= 4):
            bad.append("tags %s" % c["id"])
        if "effect" in c:
            if c["effect"] not in EFFECTS:
                bad.append("effect %s" % c["effect"])
            if c["targeting"] not in TARGETING:
                bad.append("targeting %s" % c["targeting"])
    print(name, "cards:", len(deck["cards"]), "problems:", len(bad))
    for b in bad:
        print("   !", b)
    return bad

def main():
    decks = [("backpack", build(("backpack", "Рюкзак", "🎒"), BACKPACK)),
             ("facts", build(("fact", "Доп. сведение", "📎"), FACTS)),
             ("specials", build(("special", "Спец. возможность", "⚡"), SPECIALS))]
    problems = 0
    counts = {}
    for name, deck in decks:
        problems += len(check(name, deck))
        counts[name] = len(deck["cards"])
        path = os.path.join(OUT, name + ".json")
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            json.dump(deck, f, ensure_ascii=False, indent=2)
            f.write("\n")
        print("wrote", path)
    eff = {}
    for c in SPECIALS:
        eff[c[5]] = eff.get(c[5], 0) + 1
    print("effect coverage:", json.dumps(eff, ensure_ascii=False))
    print("TOTAL problems:", problems)

main()
